def max_product(num_str: str, N: int, K: int) -> int:
    if not num_str.isdigit() or N <= 0 or K < 0 or K >= N:
        raise ValueError("Invalid input: num_str must be a digit string, N must be positive, and 0 <= K < N.")

    def split_and_multiply(parts):
        product = 1
        for part in parts:
            product *= int(part)
        return product

    max_product = 0
    from itertools import combinations

    # Generate all possible positions to insert K multiplication signs
    for positions in combinations(range(1, N), K):
        parts = []
        start = 0
        for pos in positions:
            parts.append(num_str[start:pos])
            start = pos
        parts.append(num_str[start:])

        current_product = split_and_multiply(parts)
        if current_product > max_product:
            max_product = current_product

    return max_product

