def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> str:
        # Remove hyphens and convert to list of characters
        chars = isbn.replace('-', '')
        total = 0
        for i in range(9):
            total += int(chars[i]) * (10 - i)
        checksum = 11 - (total % 11)
        return 'X' if checksum == 10 else str(checksum % 11)

    try:
        # Validate format
        if len(isbn) != 13 or isbn[1] != '-' or isbn[5] != '-' or isbn[11] != '-':
            raise ValueError("Invalid ISBN format")

        # Extract parts
        prefix, group, registrant, publication, checksum = isbn.split('-')

        # Calculate expected checksum
        expected_checksum = calculate_checksum(isbn[:-1])

        # Compare calculated checksum with provided checksum
        if checksum == expected_checksum:
            return "Right"
        else:
            # Correct the ISBN
            return f"{prefix}-{group}-{registrant}-{expected_checksum}"

    except (ValueError, IndexError):
        return "Invalid ISBN format"

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    if M <= 0 or N <= 0 or K < 0 or L < 0 or D < 0:
        raise ValueError("Invalid dimensions or number of aisles/chatting pairs.")
    if K > M - 1 or L > N - 1:
        raise ValueError("Too many aisles for the given dimensions.")
    if any(len(pair) != 4 for pair in chatting_pairs):
        raise ValueError("Each chatting pair must be represented by four integers.")

    horizontal_counts = [0] * (M + 1)
    vertical_counts = [0] * (N + 1)

    for (Xi, Yi, Pi, Qi) in chatting_pairs:
        if not (1 <= Xi <= M and 1 <= Yi <= N and 1 <= Pi <= M and 1 <= Qi <= N):
            raise ValueError("Chatting pair positions are out of bounds.")

        if Xi == Pi:  # Same row, vertical aisle can separate
            if Yi < Qi:
                vertical_counts[Yi] += 1
            else:
                vertical_counts[Qi] += 1
        elif Yi == Qi:  # Same column, horizontal aisle can separate
            if Xi < Pi:
                horizontal_counts[Xi] += 1
            else:
                horizontal_counts[Pi] += 1

    # Find the top K horizontal and L vertical positions
    horizontal_positions = sorted(range(1, M), key=lambda x: horizontal_counts[x], reverse=True)[:K]
    vertical_positions = sorted(range(1, N), key=lambda x: vertical_counts[x], reverse=True)[:L]

    return (' '.join(map(str, sorted(horizontal_positions))), ' '.join(map(str, sorted(vertical_positions))))

def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        raise ValueError("Number of students must be positive and number of passes must be non-negative.")
    if n == 1:
        return 1 if m == 0 else 0

    # dp[i][j] will be the number of ways to reach student i after j passes
    dp = [[0] * (m + 1) for _ in range(n)]
    dp[0][0] = 1

    for passes in range(1, m + 1):
        for student in range(n):
            left_neighbor = (student - 1) % n
            right_neighbor = (student + 1) % n
            dp[student][passes] = dp[left_neighbor][passes - 1] + dp[right_neighbor][passes - 1]

    return dp[0][m]

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    if n < 0 or m < 0:
        raise ValueError("Budget and number of items must be non-negative.")
    if not all(isinstance(item, tuple) and len(item) == 2 for item in items):
        raise ValueError("Items must be a list of tuples with two integers each.")
    if not all(isinstance(price, int) and isinstance(value, int) and price >= 0 and value >= 0 for price, value in items):
        raise ValueError("Item prices and values must be non-negative integers.")

    dp = [0] * (n + 1)
    for price, value in items:
        for budget in range(n, price - 1, -1):
            dp[budget] = max(dp[budget], dp[budget - price] + price * value)

    return dp[n]

def max_energy(beads):
    if not beads or len(beads) < 3:
        return 0

    n = len(beads)
    beads = [0] + beads + [0]  # Add dummy beads to handle circular nature
    dp = [[0] * (n + 2) for _ in range(n + 2)]

    for length in range(2, n + 2):
        for i in range(1, n + 2 - length):
            j = i + length - 1
            for k in range(i + 1, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j])

    return dp[1][n + 1]

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    if not isinstance(n, int) or not isinstance(coeffs, list) or len(coeffs) != n + 1:
        raise ValueError("Invalid input: n must be an integer and coeffs must be a list of length n+1.")

    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue

        sign = '+' if coeff > 0 else '-'
        abs_coeff = abs(coeff)

        if abs_coeff == 1 and degree != 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)

        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''

        if not terms:
            terms.append(f'{abs_coeff}{var_str}' if coeff > 0 else f'-{abs_coeff}{var_str}')
        else:
            terms.append(f'{sign}{coeff_str}{var_str}')

    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

    if len(mapping) != len(set(original)):
        return "Failed"

    try:
        decoded_message = ''.join(mapping[m] for m in message)
    except KeyError:
        return "Failed"

    return decoded_message

def largest_prime_factor(n: int) -> int:
    if n <= 1:
        raise ValueError("Input must be a positive integer greater than 1.")

    # Start checking from the smallest prime number
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            # Since n is the product of exactly two distinct primes, n // i will be the larger prime
            return n // i

    # If no factors are found, n itself is a prime number (though per problem statement, this case shouldn't occur)
    return n

def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x:
        return 0
    if k == 1:
        return 1 if n >= x else 0
    if k == 0:
        return 1 if n == 0 else 0

    def helper(n, k, x, start):
        if k == 0:
            return 1 if n == 0 else 0
        if n < k * x:
            return 0
        count = 0
        for i in range(start, n // k + 1):
            if i < x:
                continue
            count += helper(n - i, k - 1, x, i)
        return count

    return helper(n, k, x, x)

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last < 1 or n < 1:
        return 0
    if last == 1:
        return 1
    if last in memo:
        return memo[last]

    count = 1  # The sequence consisting of just the starting number
    for i in range(1, last // 2 + 1):
        count += count_sequences(n, i, memo)

    memo[last] = count
    return count

def count_coprime_pairs(x0: int, y0: int) -> int:
    if x0 <= 0 or y0 <= 0:
        raise ValueError("Both x0 and y0 must be positive integers.")
    if y0 % x0 != 0:
        return 0

    def gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    count = 0
    quotient = y0 // x0

    for a in range(1, int(quotient**0.5) + 1):
        if quotient % a == 0:
            b = quotient // a
            if gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2

    return count

def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder or len(inorder) != len(postorder):
        raise ValueError("Inorder and postorder traversals must be non-empty and of the same length.")

    def build_tree(in_start, in_end, post_start, post_end):
        if post_start > post_end or in_start > in_end:
            return None

        root_value = postorder[post_end]
        root_index = inorder.index(root_value, in_start, in_end + 1)

        left_tree_size = root_index - in_start

        root = {
            'value': root_value,
            'left': build_tree(in_start, root_index - 1, post_start, post_start + left_tree_size - 1),
            'right': build_tree(root_index + 1, in_end, post_start + left_tree_size, post_end - 1)
        }

        return root

    def preorder(node):
        if not node:
            return ''
        return node['value'] + preorder(node['left']) + preorder(node['right'])

    tree = build_tree(0, len(inorder) - 1, 0, len(postorder) - 1)
    return preorder(tree)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    from collections import deque

    if A == B:
        return 0

    queue = deque([(A, 0)])
    visited = set([A])

    while queue:
        current, steps = queue.popleft()

        if steps >= 10:
            continue

        for src, tgt in rules:
            start = 0
            while start <= len(current) - len(src):
                pos = current.find(src, start)
                if pos != -1:
                    new_string = current[:pos] + tgt + current[pos + len(src):]
                    if new_string == B:
                        return steps + 1
                    if new_string not in visited:
                        visited.add(new_string)
                        queue.append((new_string, steps + 1))
                else:
                    break
                start = pos + 1

    return "NO ANSWER!"

def find_min_n_greater_than_k(k: int) -> int:
